from pathlib import Path
from fractions import Fraction as F
import datetime,hashlib,json,os
p=Path('docs/evidence/appearance-2026-10-19/sequential-material-cell')
def load(name):return json.loads((p/name).read_text())
def dec(x):
 if isinstance(x,dict):
  if set(x)=={'n','d'}:return F(x['n'],x['d'])
  return {k:dec(v)for k,v in x.items()}
 if isinstance(x,list):return [dec(v)for v in x]
 return x
def rat(x):return F(*x.as_integer_ratio())
def dot(a,b):return sum(x*y for x,y in zip(a,b))
def sub(a,b):return [x-y for x,y in zip(a,b)]
def cross(a,b):return [a[1]*b[2]-a[2]*b[1],a[2]*b[0]-a[0]*b[2],a[0]*b[1]-a[1]*b[0]]
def rank(points):
 if not points:return -1
 rows=[sub(v,points[0])for v in points[1:]]
 pivot=0
 for axis in range(3):
  hit=next((i for i in range(pivot,len(rows))if rows[i][axis]),None)
  if hit is None:continue
  rows[pivot],rows[hit]=rows[hit],rows[pivot]
  divisor=rows[pivot][axis];rows[pivot]=[x/divisor for x in rows[pivot]]
  for i in range(len(rows)):
   if i!=pivot:
    factor=rows[i][axis];rows[i]=[x-factor*y for x,y in zip(rows[i],rows[pivot])]
  pivot+=1
  if pivot==3:break
 return pivot
raw=(p/'RESULT.json').read_bytes();rawdata=json.loads(raw);x=dec(rawdata)
tool=load('PACKET-TOOL-RESULT.json');stdout=json.loads(tool['output'])
assert tool['exit_code']==0 and stdout['status']=='PACKET_PASS' and stdout['candidate_calls']==34
assert stdout['result_bytes']==len(raw)==422931 and stdout['result_sha256']==hashlib.sha256(raw).hexdigest()=='4c5e0b09385846f269359602d9bf7c1bb3bb655acb9c747f9d350acf0ef8a51a'
admission=load('ROOT-ADMISSION.json');claim=load('CLAIM.json')
assert admission['admitted'] is True and claim['pid']==x['pid']==stdout['pid']==76360 and claim['attempt']==1
assert claim['admission_sha256']==hashlib.sha256((p/'ROOT-ADMISSION.json').read_bytes()).hexdigest()
for name,sha in admission['sha256'].items():assert hashlib.sha256((p/name).read_bytes()).hexdigest()==sha
refpath=p.parents[1]/'appearance-2026-10-18/material-cell-oracle/RESULT.json'
refraw=refpath.read_bytes();ref=json.loads(refraw)
assert hashlib.sha256(refraw).hexdigest()==admission['reference_sha256']==x['reference_sha256']
assert x['status']=='PACKET_PASS' and x['candidate_calls']==len(x['observations'])==34 and x['failure'] is None
assert all(o['passed'] is True for o in x['observations']) and not(p/'__pycache__').exists()
geometry=('dimension','vertices','facets','volume','edge_count')
for i,row in enumerate(rawdata['observations'][:17]):
 old=ref['observations'][i];assert row['reference_index']==i and row['inputs']==old['inputs']
 assert row['actual']['status']==old['actual']['status'] and row['expected']==old['actual']
 for key in geometry:
  if key in old['actual']:assert row['actual'][key]==old['actual'][key],(i,key)
invalid_names=['duplicate_gids','nonfinite_point','label','orientation','cut_names','cut_count','ratio']
for row,name in zip(rawdata['observations'][17:24],invalid_names):
 assert row['name']=='invalid:'+name and row['expected']=='ValueError' and row['actual']['exception']=='ValueError'
rows=x['observations'];fresh=rows[24:]
assert [r['name']for r in fresh]==['fresh:'+s for s in ('plane_then_quad','plane_then_point','plane_then_empty','edge_then_segment','edge_then_empty','point_then_empty','constant_empty','skewed_translated_slab','reversed_cut_order','coincident_then_point')]
fixed_positions={0:{(F(0),F(0),F(0)),(F(0),F(1,2),F(0)),(F(0),F(1,2),F(1,2)),(F(0),F(0),F(1))},1:{(F(0),F(1,4),F(1,4))},3:{(F(1,4),F(0),F(0)),(F(1,2),F(0),F(0))},9:{(F(0),F(0),F(0))}}
for i,positions in fixed_positions.items():
 assert {tuple(v['position'])for v in fresh[i]['actual']['vertices']}==positions
for i in (2,4,5,6):assert fresh[i]['actual']['status']=='EMPTY'
assert fresh[7]['actual']['volume']==F(19,64)
for key in geometry:assert rawdata['observations'][32]['actual'][key]==ref['observations'][4]['actual'][key]
oldslab=dec(ref['observations'][1]['actual']);newslab=fresh[7]['actual']
for old,new in zip(oldslab['vertices'],newslab['vertices']):
 ox,oy,oz=old['position'];assert new['position']==[3+2*ox+oy/2,-2+oy+oz/4,5+3*oz]
 assert {k:v for k,v in new.items()if k!='position'}=={k:v for k,v in old.items()if k!='position'}
for old,new in zip(oldslab['facets'],newslab['facets']):
 nx,ny,nz=old['normal_world'];gx=nx/2;gy=ny-gx/2
 assert new['normal_world']==[gx,gy,(nz-gy/4)/3]
 assert {k:v for k,v in new.items()if k!='normal_world'}=={k:v for k,v in old.items()if k!='normal_world'}
counts={};totals={'OK_cells':0,'OK_vertices':0,'OK_facets':0,'OK_fan_triangles':0,'degenerate_vertices':0}
for o in rows:
 a=o['actual'];status=a.get('status',a.get('exception'));counts[status]=counts.get(status,0)+1
 if status not in ('OK','DEGENERATE'):continue
 d=o['inputs'];gids=d['gids'];points={g:tuple(map(rat,pnt))for g,pnt in zip(gids,d['points'])};labels=dict(zip(gids,d['labels']))
 fields={name:dict(zip(gids,map(rat,vs)))for name,vs in d['cuts']}
 vs=a['vertices'];keys=[]
 for v in vs:
  w=dict(v['weights']);assert set(w)==set(gids)and min(w.values())>=0 and sum(w.values())==1
  support=sorted(g for g in gids if w[g]>0);active=[]
  for name,samples in fields.items():
   value=sum(w[g]*samples[g]for g in gids);assert value<=0
   if value==0:active.append(name)
  assert v['key']==[support,sorted(active)]
  assert v['position']==[sum(w[g]*points[g][axis]for g in gids)for axis in range(3)]
  assert v['u']==[w[g]for g in gids[1:]]
  assert v['regions']==sorted(set().union(*(labels[g]for g in support)))
  keys.append((tuple(support),tuple(sorted(active))))
 assert keys==sorted(set(keys))and rank([v['position']for v in vs])==a['dimension']
 if status=='DEGENERATE':
  assert a['facets']==[]and a['volume']==0;totals['degenerate_vertices']+=len(vs);continue
 edges={};used=set();volume=F(0);totals['OK_cells']+=1;totals['OK_vertices']+=len(vs)
 for face in a['facets']:
  cycle=face['vertices'];assert len(cycle)==len(set(cycle))>=3 and keys[cycle[0]]==min(keys[i]for i in cycle)
  if face['kind']=='cut':samples=fields[face['owner']]
  else:
   assert face['kind']=='tet'and len(set(face['owner']))==3 and set(face['owner'])<set(gids)
   samples={g:F(0 if g in face['owner']else-1)for g in gids}
  n=face['normal_world'];assert rank([vs[i]['position']for i in cycle])==2
  for g in gids[1:]:assert dot(n,sub(points[g],points[gids[0]]))==samples[g]-samples[gids[0]]
  for i in cycle:
   assert sum(w*samples[g]for g,w in vs[i]['weights'])==0
   assert dot(n,sub(vs[i]['position'],points[gids[0]]))+samples[gids[0]]==0
  allfields=list(fields.values())+[{g:F(-int(g==omitted))for g in gids}for omitted in gids]
  assert sum(all(sum(w*s[g]for g,w in vs[i]['weights'])==0 for i in cycle)for s in allfields)==1
  union=sorted(set().union(*(vs[i]['regions']for i in cycle)));assert face['regions']==union
  assert [t['vertices']for t in face['triangles']]==[[cycle[0],cycle[j],cycle[j+1]]for j in range(1,len(cycle)-1)]
  for t in face['triangles']:
   assert t['regions']==union
   pa,pb,pc=[vs[i]['position']for i in t['vertices']]
   assert dot(n,cross(sub(pb,pa),sub(pc,pa)))>0
   volume+=dot(pa,cross(pb,pc))/6;totals['OK_fan_triangles']+=1
  for aa,bb in zip(cycle,cycle[1:]+cycle[:1]):edges.setdefault(tuple(sorted((aa,bb))),[]).append((aa,bb))
  used.update(cycle);totals['OK_facets']+=1
 assert used==set(range(len(vs))) and all(len(e)==2 and e[0]==e[1][::-1]for e in edges.values())
 assert len(vs)-len(edges)+len(a['facets'])==2 and a['edge_count']==len(edges) and a['volume']==volume>0
assert counts=={'OK':12,'EMPTY':5,'DEGENERATE':7,'REFUSED':2,'UNKNOWN':1,'ValueError':7}
out={'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'pid':os.getpid(),'decision':'ROOT_NUMERIC_PASS_AWAIT_INDEPENDENT_RESULT_REVIEW','packet_job':'006caa/exit0/PID76360','packet_started':x['utc_started'],'packet_finished':x['utc_finished'],'packet_elapsed_after_imports':x['elapsed_seconds_after_imports'],'reference_rows_exact':17,'invalid_rows':7,'fresh_rows':10,'status_counts':counts,'totals':totals,'result_bytes':len(raw),'result_sha256':hashlib.sha256(raw).hexdigest(),'checks':['Actual collected exit/stdout/result/admission/claim/source/reference exact bindings','All17 full frozen geometric outputs compared without target/oracle calls','Fresh exact positions/statuses, transformed world positions/normals and determinant6 volume, reversed box exact outputs','Independent saved-data Gaussian rank for every OK/DEGENERATE output','Every vertex full support/active IDs/feasible weights/exact world position/labels','Every actual facet unique input owner, world normal equations, point planes, canonical fans/whole polygon label union','All opposed edges/Euler/used vertices/exact positive signed volume'],'observer_errors':[],'limits':'No candidate/helper/oracle/old fixture imported or called; saved-result arithmetic only. No global assembly, arbitrary-input proof, source eligibility, field, garment, physical, motion, appearance or performance credit.'}
with(p/'ROOT-RESULT.json').open('x')as f:json.dump(out,f,indent=2);f.write('\n')
print(json.dumps(out,indent=2))
